"use client";
import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
  type RefObject,
  type PointerEvent,
} from "react";
import { sectionClamp, sectionWrap } from "./section-math";
export interface SectionInternalMedia {
  src?: string;
  alt?: string;
  content?: ReactNode;
}
export interface SectionInternalItem extends SectionInternalMedia {
  id: string;
  title: string;
  description?: string;
}
export interface SectionInternalBase {
  className?: string;
  style?: CSSProperties;
  height?: number;
  label?: string;
}
export interface SectionInternalLink {
